from pathlib import Path
import hashlib,json,os,sqlite3,stat,subprocess,sys
out=Path(__file__).resolve().parent;f=json.loads((out/'fixture.json').read_text());root=Path(f['workspace_root'])
def snap():return {str(p.relative_to(root)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':stat.S_IMODE(p.stat().st_mode)} for p in root.rglob('*') if p.is_file()}
def git(key,*args):return subprocess.check_output(['git','-c','diff.autoRefreshIndex=false','-C',f[key],*args],env=dict(os.environ,GIT_OPTIONAL_LOCKS='0',GIT_CONFIG_GLOBAL='/dev/null',GIT_CONFIG_NOSYSTEM='1'))
current=snap();before=json.loads((out/'before.json').read_text());allowed='parent/.git/modules/middle/';assert {k:v for k,v in current.items() if not k.startswith(allowed)}=={k:v for k,v in before.items() if not k.startswith(allowed)};leaf_meta='parent/.git/modules/middle/modules/leaf/';assert {k:v for k,v in current.items() if k.startswith(leaf_meta)}=={k:v for k,v in before.items() if k.startswith(leaf_meta)}
assert git('parent','rev-parse','HEAD').strip()==b'8df29fca0127da252cf1fb2c3923670b3e37d715';assert git('leaf','rev-parse','HEAD').strip()==b'4b6e1ea1dbeabd9350368a24ad83206366dc7608';assert git('middle','rev-list','--count','949253cc316c4811271f4eb272f1196a8027d10e..HEAD').strip()==b'1';assert git('middle','show','HEAD:file.txt')==b'G05 explicitly selected middle only\n';assert git('middle','log','-1','--format=%B')==b'G05 preserve dirty unselected submodule\n\n';assert git('middle','diff-tree','--no-commit-id','--name-only','-r','HEAD').splitlines()==[b'file.txt'];assert git('middle','rev-parse','HEAD:leaf')==git('leaf','rev-parse','HEAD');assert git('leaf','status','--porcelain')==b' M file.txt\n';assert git('middle','status','--porcelain','--ignore-submodules=all')==b''
c=sqlite3.connect('file:'+f['state']+'/state.db?mode=ro',uri=True);records={'operations':dict(c.execute('select id,payload from write_operations')),'batches':dict(c.execute("select key,value from state where key like 'batch:%'"))};previous=json.loads((out/'records-before.json').read_text());assert all(records[kind][k]==v for kind in previous for k,v in previous[kind].items());new_batches={k:json.loads(v) for k,v in records['batches'].items() if k not in previous['batches']};assert {k:v['phase'] for k,v in new_batches.items()}=={'batch:bbf599f7-e45a-4b97-a13f-9f352f6dd687':'cancelled','batch:6d532c45-8cd4-42bc-9d78-84b8335c9866':'complete'}
for batch in new_batches.values():assert len(batch['items'])==1 and batch['items'][0]['worktree']==f['entries'][f['middle']]
assert len(set(records['operations'])-set(previous['operations']))==2
assert set(c.execute('select worktree_id,revoked from write_trust'))=={(f['entries'][f[k]],1 if k=='parent' else 0) for k in ['parent','middle','leaf']};assert c.execute('pragma integrity_check').fetchone()[0]=='ok';assert snap()==current
label=sys.argv[1];proof={'stage':label,'one_middle_commit':git('middle','rev-parse','HEAD').decode().strip(),'unselected_dirty_leaf_checkout_metadata_exact':True,'revoked_ancestor_and_control_exact':True,'only_explicit_middle_enrolled':True,'exact_content_message_unchanged_gitlink':True,'working_files_modes_preserved':True,'prior_records_unchanged':True,'parent_remains_revoked_no_grants':True,'integrity':'ok'}
if label=='before-restart':(out/'final-files.json').write_text(json.dumps(current,indent=2)+'\n');(out/'final-records.json').write_text(json.dumps(records,indent=2)+'\n')
else:assert current==json.loads((out/'final-files.json').read_text());assert records==json.loads((out/'final-records.json').read_text());proof['restart_exact_files_records_no_replay']=True
(out/('verify-'+label+'.json')).write_text(json.dumps(proof,indent=2)+'\n');print(proof)
